/* Browser-only Google Drive adapter. Access token stays in memory, never in backups. */
(function(root){
 'use strict';
 const SCOPE='https://www.googleapis.com/auth/drive.appdata',BASE='https://www.googleapis.com/drive/v3/';
 let token='',expires=0,subject='',scriptPromise;
 function clear(){token='';expires=0;subject=''}
 function ready(){return !!token&&Date.now()<expires}
 async function request(url,options={}){if(!ready())throw Error('Google 연결이 만료됐습니다. 다시 연결하세요.');const response=await fetch(url,{...options,headers:{...options.headers,Authorization:'Bearer '+token},signal:AbortSignal.timeout(30000),cache:'no-store',credentials:'omit',redirect:'error'});if(response.status===401){clear();throw Error('Google 연결이 만료됐습니다. 다시 연결하세요.')}if(response.status===403||response.status===429)throw Error('Google Drive 권한 또는 요청 한도에 도달했습니다. 잠시 후 직접 재시도하세요.');if(!response.ok)throw Error('Google Drive 요청 실패 ('+response.status+')');return response}
 function sdk(){if(root.google?.accounts?.oauth2)return Promise.resolve();if(scriptPromise)return scriptPromise;scriptPromise=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://accounts.google.com/gsi/client';s.async=true;const timer=setTimeout(()=>{scriptPromise=null;s.remove();reject(Error('Google 로그인 준비 시간이 초과됐습니다. 인터넷 연결을 확인하고 다시 시도하세요.'))},15000);s.onload=()=>{clearTimeout(timer);resolve()};s.onerror=()=>{clearTimeout(timer);scriptPromise=null;s.remove();reject(Error('Google 로그인 파일을 불러오지 못했습니다. 인터넷 연결을 확인하세요.'))};document.head.append(s)});return scriptPromise}
 // Prepare SDK first; connection itself must be triggered by another user click (popup blockers).
 async function prepare(){await sdk()}
 function connect(clientId){if(!/^[a-zA-Z0-9_-]+\.apps\.googleusercontent\.com$/.test(clientId))return Promise.reject(Error('웹 OAuth 클라이언트 ID를 확인하세요.'));if(!root.google?.accounts?.oauth2)return Promise.reject(Error('먼저 Google 로그인 준비를 눌러 주세요.'));clear();return new Promise((resolve,reject)=>{const client=google.accounts.oauth2.initTokenClient({client_id:clientId,scope:'openid '+SCOPE,callback:async r=>{try{if(r.error||!r.access_token)throw Error('Google 연결이 취소되었거나 거부되었습니다.');if(!google.accounts.oauth2.hasGrantedAllScopes(r,SCOPE,'openid'))throw Error('앱 데이터 접근 권한이 필요합니다.');token=r.access_token;expires=Date.now()+(Number(r.expires_in)-60)*1000;const response=await request('https://openidconnect.googleapis.com/v1/userinfo');const user=await response.json();if(typeof user.sub!=='string'||!/^[a-zA-Z0-9_-]{1,128}$/.test(user.sub))throw Error('Google 계정을 확인하지 못했습니다.');subject=user.sub;resolve(subject)}catch(e){clear();reject(e)}},error_callback:()=>{clear();reject(Error('로그인 창이 닫혔거나 차단되었습니다.'))}});client.requestAccessToken({prompt:'select_account'})})}
 async function list(){let pageToken,files=[];do{const q=new URLSearchParams({spaces:'appDataFolder',q:"trashed = false and appProperties has { key='akaSync' and value='v1' }",fields:'nextPageToken,files(id,size,name)',pageSize:'100'});if(pageToken)q.set('pageToken',pageToken);const data=await (await request(BASE+'files?'+q)).json();if(!Array.isArray(data.files))throw Error('Drive 목록 응답 오류');files.push(...data.files);if(files.length>1000)throw Error('베타 동기화 파일 한도(1,000개)에 도달했습니다. 기존 데이터는 보존됩니다.');pageToken=data.nextPageToken}while(pageToken);if(files.reduce((n,f)=>n+Number(f.size||0),0)>50*1024*1024)throw Error('베타 동기화 전체 용량 한도(50MB)에 도달했습니다.');return files}
 async function read(file){if(!/^[a-zA-Z0-9_-]+$/.test(file.id)||Number(file.size)>25*1024*1024)throw Error('지원하지 않는 동기화 파일');const response=await request(BASE+'files/'+file.id+'?alt=media');const reader=response.body.getReader(),chunks=[];let bytes=0;for(;;){const {value,done}=await reader.read();if(done)break;bytes+=value.length;if(bytes>25*1024*1024){await reader.cancel();throw Error('동기화 파일 용량 초과')}chunks.push(value)}return new Blob(chunks).text()}
 async function upload(text){if(new TextEncoder().encode(text).length>25*1024*1024)throw Error('동기화 업로드는 25MB 이하만 지원합니다.');const boundary='aka-'+crypto.randomUUID(),metadata={name:'AKA-Sheet-sync-'+crypto.randomUUID()+'.json',mimeType:'application/json',parents:['appDataFolder'],appProperties:{akaSync:'v1'}},body='--'+boundary+'\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n'+JSON.stringify(metadata)+'\r\n--'+boundary+'\r\nContent-Type: application/json\r\n\r\n'+text+'\r\n--'+boundary+'--';return (await request('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id',{method:'POST',headers:{'Content-Type':'multipart/related; boundary='+boundary},body})).json()}
 root.DriveClient={prepare,connect,ready,clear,list,read,upload,account:()=>subject};
})(globalThis);
